cd /tmp/sv-6ec034acf8f046cb84a3a6087d0def64/simple-solution && dotnet list package --format json 2>/dev/null | tee after-cpm-packages.json | python3 -c "
import json, sys
d = json.load(sys.stdin)
for p in d['projects']:
    name = p['path'].split('/')[-1]
    for fw in p['frameworks']:
        for pkg in fw['topLevelPackages']:
            print(f'{name}: {pkg[\"id\"]} {pkg[\"resolvedVersion\"]}')
"

